def seasonal_naive(train, h):
    # forecast using values 12 months back
    idx = [len(train)-12+i for i in range(h)]
    return np.array(train.iloc[idx])

def seasonal_drift(train, h):
    # last season plus avg yoy diff over available same season? apply trend per year = (last 12 avg - previous 12 avg)
    last12=train.iloc[-12:].mean()
    prev12=train.iloc[-24:-12].mean() if len(train)>=24 else train.iloc[:-12].mean()
    diff=last12-prev12
    base=seasonal_naive(train,h)
    return base + diff # one year drift

def ets_forecast(train,h, trend='add', seasonal='add'):
    return ExponentialSmoothing(train, trend=trend, seasonal=seasonal, seasonal_periods=12, initialization_method='estimated').fit().forecast(h).values

def sarima_fixed(train,h):
    try:
        return SARIMAX(train, order=(0,1,1), seasonal_order=(0,1,1,12), trend='n',
                       enforce_stationarity=False, enforce_invertibility=False).fit(disp=False, maxiter=200).forecast(h).values
    except Exception as e:
        return np.repeat(train.iloc[-1], h)

def ridge_month(train,h,alpha=1):
    idx=train.index
    Xtr=pd.get_dummies(pd.DataFrame({'t':np.arange(len(train)), 'month':idx.month}, index=idx).astype({'month':'category'}))
    futidx=pd.date_range(idx[-1]+pd.offsets.MonthBegin(1), periods=h, freq='MS')
    Xfu=pd.get_dummies(pd.DataFrame({'t':np.arange(len(train),len(train)+h), 'month':futidx.month}, index=futidx).astype({'month':'category'}))
    Xfu=Xfu.reindex(columns=Xtr.columns, fill_value=0)
    return Ridge(alpha=alpha).fit(Xtr, train.values).predict(Xfu)

methods={
    'seasonal_naive': seasonal_naive,
    'seasonal_drift': seasonal_drift,
    'ets_add_add': lambda tr,h: ets_forecast(tr,h,'add','add'),
    'ets_none_add': lambda tr,h: ets_forecast(tr,h,None,'add'),
    'sarima': sarima_fixed,
    'ridge_month1': lambda tr,h: ridge_month(tr,h,1),
    'ridge_month10': lambda tr,h: ridge_month(tr,h,10),
}
errs={m:[] for m in methods}
preds_records=[]
# rolling origins min train 24 up to len-3
for train_end in range(24, len(y)-3+1):
    train=y.iloc[:train_end]
    actual=y.iloc[train_end:train_end+3].values[-1] # h=3
    date=y.index[train_end+2]
    for name,fn in methods.items():
        try:
            pred=fn(train,3)[-1]
            errs[name].append(pred-actual)
            preds_records.append((name,date,pred,actual,pred-actual))
        except Exception as e:
            errs[name].append(np.nan)
for name, e in errs.items():
    e=np.array(e,dtype=float)
    print(name, 'n', np.isfinite(e).sum(), 'MAE', np.nanmean(abs(e)), 'RMSE', np.sqrt(np.nanmean(e**2)), 'MAPE', np.nanmean(abs(e)/[r[3] for r in preds_records if r[0]==name]))

for name,fn in methods.items():
    try:
        print(name, fn(y,3)[-1])
    except Exception as e: print(e)
# ensemble avg best
vals={name:fn(y,3)[-1] for name,fn in methods.items() if name!='sarima'}
np.mean(list(vals.values())), np.median(list(vals.values())), vals

rmses={}
for name,e in errs.items():
    e=np.array(e,dtype=float)
    if name!='sarima': rmses[name]=np.sqrt(np.nanmean(e**2))
weights={name:1/r**2 for name,r in rmses.items()}
s=sum(weights.values())
weights={k:v/s for k,v in weights.items()}
ens=sum(weights[k]*vals[k] for k in vals)
weights, ens
